"""Supplementary static compositions for the design lock. No API or form runtime."""
from pathlib import Path
import json,shutil,html
root=Path(__file__).resolve().parents[1]; dest=root/'design/phase20';dest.mkdir(exist_ok=True,parents=True)
shutil.copytree(root/'design/phase16/brand',dest/'brand',dirs_exist_ok=True)
css=(root/'design/phase16/style.css').read_text(encoding='utf-8')+'''
.lock-note{padding:12px 0;border-bottom:1px solid var(--line);font-size:13px;color:var(--muted)}.lock-body{padding:28px 0 56px}.lock-body h1{font-size:36px;margin-bottom:18px}.lock-body h2{font-size:25px;margin:12px 0 18px}.lock-body .case-panel{min-width:0}.lock-body input{width:100%;min-height:46px;background:var(--bg);border:1px solid var(--line);color:var(--paper);padding:12px}.lock-body label{display:block;margin:14px 0}.lock-body code{display:block;margin:12px 0}.lock-body .primary:disabled,.lock-body .secondary:disabled{opacity:.65;cursor:default}.lock-body .rule{border-top:1px solid var(--line);padding-top:18px;margin-top:18px}.reading{max-width:760px;margin:24px auto}.reading p{font-size:17px;line-height:1.8}.reading h2{margin-top:28px}.tier{padding:20px 0;border-top:1px solid var(--line)}.tier h2{font-size:23px}.layout-links{display:grid;grid-template-columns:1fr 1fr;gap:12px}.layout-links a{border-top:1px solid var(--line);min-height:60px;padding:16px 0;color:var(--green)}@media(max-width:760px){.lock-body h1{font-size:30px}.layout-links{grid-template-columns:1fr}}
'''
(dest/'style.css').write_text(css,encoding='utf-8')
case=json.loads((root/'design/phase16/case-data.json').read_text())
E=html.escape
blob=E(case['blob']);job=E(case['job'])
sources='<p class="caption">Recorded source incident</p><code>'+E(case['source'])+'</code><p class="caption">This example is an independent integration procedure. Original operator deployment remains unknown.</p>'
states={
'unconfirmed':('Storage response unconfirmed','<p>No accepted job ID was received. The request may have reached storage. Do not submit another copy.</p><label>Existing storage job ID<input disabled placeholder="Recover the existing job ID"></label><button class="secondary" disabled>Check existing job</button><p class="caption rule">No blob or completed-memory claim. Preserve the attempt identity locally; recovery checks an existing job.</p>'),
'rejected':('Review was not accepted','<p>The review needs correction before it can be stored. No accepted job or completed memory is claimed.</p><div class="error-summary"><strong>Correct the review</strong><p>Example validation state: enter the evidence URL required by the selected proof method.</p></div><label>Evidence URL<input disabled placeholder="Immutable commit or merged PR" aria-invalid="true" aria-describedby="url-error"></label><p id="url-error">Enter the evidence URL.</p><p class="caption rule">Keep entered review fields. Authentication failure uses access guidance instead of blaming this field. No approvals are preselected.</p>'),
'failed-job':('Storage job failed','<p>This accepted job ended in failure. It has no completed-memory receipt.</p><span class="label">Recorded job identity for layout only</span><code>'+job+'</code><button class="secondary" disabled>Dismiss failed job</button><p class="caption rule">Dismissal is an explicit local recovery action. It does not silently submit the case again.</p>'),
'access':('Reviewer access','<p>Public transaction inspection stays separate from protected reviewer writes.</p><label>Private reviewer key<input type="password" disabled placeholder="Enter privately in the implemented app"></label><p class="caption">Never include this value in URLs, evidence captures or live announcements.</p><div class="rule"><strong>Public example mode</strong><p>The public demo supports the supplied example digests. Explain this next to intake only when that actual mode is active.</p><strong>Authorized mode</strong><p>Authenticated inspection uses the existing server policy. Do not show the public-example restriction here.</p></div><p class="caption">This static access composition cannot receive a key or unlock anything.</p>'),
'memory-unconfigured':('Memory is not configured','<p>Transaction evidence can still be inspected when Tatum is configured. Reviewed memory cannot be searched until the operator configures Walrus.</p><p>No memory result or zero-case conclusion is implied.</p><div class="rule"><strong>Separate configuration states</strong><p>Tatum unavailable: disable transaction inspection and show setup guidance. Walrus unavailable: preserve chain read. Reviewer access missing: protect writes while leaving permitted reads available.</p></div>'),
'tiers':('Evidence has different strengths','<section class="tier"><span class="label">HUMAN-REVIEWED RESOLUTION</span><h2>A procedure with causal evidence and human approval.</h2><p>Only an eligible reviewed case uses the reviewed-procedure composition. Source, reviewer, limits and exact blob remain visible.</p></section><section class="tier"><span class="label">OBSERVATION ONLY</span><h2>A recorded failure is not a confirmed fix.</h2><p>Show the observed transaction and original evidence. No reviewed-resolution badge or reuse recommendation.</p></section><section class="tier"><span class="label">SIMULATION-TESTED RUNBOOK</span><h2>A controlled procedure with explicit limits.</h2><p>Keep reproduction evidence and simulation qualification adjacent. It is not a deployed correction or the approved reviewed cancellation case.</p></section>'),
'inventory':('Completed-memory inventory','<p>Inventory unavailable. No conclusion about the number of completed records can be drawn.</p><button class="secondary" disabled>Retry inventory read</button><div class="rule"><p>When available, show the actual unique completed count for the active namespace, labelled all record types. Pending jobs are excluded. Never turn an unavailable or partial response into zero.</p><p class="caption">Do not hardcode the recorded inventory of 13 into the live interface.</p></div>')}
def page(name,title,body,kind='workspace'):
    content=('<div class="case-layout"><section class="case-panel"><span class="label">CURRENT EVIDENCE / STATIC CONTEXT</span><h2>Keep the source in view.</h2>'+sources+'</section><section class="case-panel"><h2>'+E(title)+'</h2>'+body+'</section></div>') if kind=='workspace' else body
    doc='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="icon" href="brand/favicon.svg"><link rel="stylesheet" href="style.css"><title>Rouse / '+E(title)+'</title></head><body><div class="study">Design lock supplement · static target · no live data or actions</div><div class="wrap"><header><a href="index.html"><img class="logo" src="brand/wordmark-light.svg" alt="Rouse"></a><nav class="nav"><a href="index.html">Composition index</a></nav></header><div class="lock-note">Supplement to Working Precedent. Disabled controls describe placement; they do not submit.</div><main class="lock-body"><h1>'+E(title)+'</h1>'+content+'</main></div></body></html>'
    (dest/(name+'.html')).write_text(doc,encoding='utf-8')
for name,(title,body) in states.items():page(name,title,body)
page('proof','Read-only simulation proof','<p>Separate historical technical experiment. Not the human-reviewed cancellation case and not an onchain repair.</p><div class="case-layout"><section class="case-panel"><span class="label">SIMULATION FAILED / CONTROLLED INPUT</span><h2>20,000,000 MIST requested</h2><p>From a 10,000,000 MIST coin. Preserve the actual error/status from the evidence artifact in implementation.</p></section><section class="case-panel"><span class="label">SIMULATION SUCCEEDED / CONTROLLED INPUT</span><h2>5,000,000 MIST requested</h2><p>From the same controlled coin structure. No execution error in the simulated result.</p></section></div><section class="case-panel rule"><h2>Evidence and limits</h2><p>Use the original simulation evidence hash, retained runbook blob and reproduction/source links from the existing route. No wallet signature or submitted transaction is claimed. Render actual artifact identifiers, never placeholders, in the real app.</p><p class="caption">This supplemental composition deliberately does not substitute the reviewed cancellation blob for the simulation record.</p></section>',kind='proof')
page('fieldnotes','Engineering field notes','<article class="reading"><div class="label">DATED ENGINEERING NOTES / HISTORICAL RECORD PRESERVED</div><h2>Reviewed knowledge for the next investigation.</h2><p>A chain record shows the failed execution. A reviewed resolution retains the reasoning and evidence another engineer needs.</p><section class="case-panel"><span class="label">7 NOVEMBER 2026 / REVIEWED INTEGRATION CASE</span><h2>Keep the verified update first.</h2><p>The approved independent reconciliation procedure was retained and its exact blob recalled for a distinct failure. Original operator deployment remains unknown.</p><code>'+blob+'</code><p class="caption">Implementation links to the immutable engineering evidence and the actual recurrence.</p></section><h2>Then preserve the earlier investigation.</h2><p>Keep the November 4 simulation narrative and original Casewake screenshots dated and labelled as historical. They are not current Rouse release captures.</p><p>Reading column: 760px maximum, 17px body with 1.8 line height. Evidence figures may extend to the workspace width when their labels remain legible; use semantic transcripts and source links rather than shrinking an image into unreadable proof.</p></article>',kind='article')
links=''.join('<a href="'+n+'.html">'+E(t)+'</a>' for n,(t,_) in states.items())+'<a href="proof.html">Historical proof page</a><a href="fieldnotes.html">Dated field notes</a>'
page('index','Design lock supplements','<p>These nine static compositions close the secondary-state and page-layout gaps. The accepted landing, eligible, review, receipt and twelve primary states remain the Phase 16 targets.</p><div class="layout-links">'+links+'</div>',kind='index')
(dest/'supplements.json').write_text(json.dumps({'pages':list(states)+['proof','fieldnotes'],'scope':'Static targets only','case':case},indent=2))
print('Built nine supplementary static targets')
